 const body=dialog.querySelector('.dialog-body'),hero=document.createElement('div');hero.className='profile-hero';hero.innerHTML=`<span class="profile-symbol ${kind==='employees'?'person-avatar':''}">${kind==='employees'?initials(row.name):icon(kind==='facilities'?facilityIcon(row):kind)}</span><div><span class="small muted">${esc(name(kind))}</span><h3>${esc(row.name)}</h3><p>${kind==='employees'?'Разряд '+num(row.qualification)+' · '+esc(row.phone||'Телефон не указан'):kind==='facilities'?esc(row.address):kind==='contracts'?esc(row.number):''}</p></div>${row.status?badge(row.status):''}`;body.prepend(hero);
