 if(kind==='shifts'){const out=await api('assignments','GET',null,{shift_id:id,limit:50});const panel=document.createElement('div');panel.className='profile-documents';panel.innerHTML='<h3>Состав смены</h3>'+out.items.map(x=>`<div class="document-row" data-record="${x.id}" data-kind="assignments"><span>${icon('employees')}</span><div><strong>${cell('employee_id',x.employee_id)}</strong><small>${esc(x.name)}</small></div>${badge(x.status)}</div>`).join('');hero.after(panel);bindRecords(panel,'assignments');}
